// Groups whose params live under a different tuning.json key than the tab id.
// (A tab can also override per-param with `g`, as Tools does for grenades.)
const TUNING_GROUP_OF = tab => tab.group || tab.id;

// ---- min/max come from src/sim/tuning_params.def --------------------------
// Every .def row's range is the loader's clamp AND this slider's range; it is
// written once, in the .def, and reaches the page through the generated
// assets/tuning_params.js (loaded before this file). A row here that names a
// .def key carries no min/max of its own -- check_invariants.py refuses one --
// so the join below is the only place the tuner learns a range. A row with no
// .def key (none today) keeps whatever it states itself.
(function joinTuningParams() {
  const P = (typeof TUNING_PARAMS !== 'undefined') ? TUNING_PARAMS
          : (typeof require !== 'undefined') ? require('./tuning_params.js').TUNING_PARAMS
          : null;
  if (!P) return;
  for (const tab of TUNING_SCHEMA) {
    for (const pr of tab.params || []) {
      const p = P[(pr.g || TUNING_GROUP_OF(tab)) + '.' + pr.k];
      if (!p) continue;
      if (p.min !== undefined) pr.min = p.min;
      if (p.max !== undefined) pr.max = p.max;
    }
  }
})();

if (typeof module !== 'undefined') module.exports = {TUNING_SCHEMA, TUNING_GROUP_OF};
